import ast

def is_safe(node):
    if isinstance(node, (ast.Constant, ast.Name)):
        return True
    if isinstance(node, ast.Compare):
        return is_safe(node.left) and all(is_safe(c) for c in node.comparators)
    if isinstance(node, (ast.BoolOp, ast.BinOp, ast.UnaryOp)):
        # BinOp might not be needed based on requirements
        if isinstance(node, ast.BoolOp):
             return all(is_safe(v) for v in node.values)
        if isinstance(node, ast.UnaryOp):
             return is_safe(node.operand)
    if isinstance(node, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.And, ast.Or, ast.Not)):
        return True
    return False

# Actually, it's better to traverse the tree and check all nodes.
def validate_node(node):
    allowed_types = (
        ast.Expression, ast.Constant, ast.Name, 
        ast.Compare, ast.BoolOp, ast.UnaryOp, 
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, 
        ast.And, ast.Or, ast.Not,
        ast.Load
    )

    if not isinstance(node, allowed_types):
        return False

    for child in ast.iter_child_nodes(node):
        if not validate_node(child):
            return False
    return True

